"""The input forms of the Economics & Finance workspace, described as data in the same vocabulary as the other subject workspaces.

Rates are typed in percent (``5`` means 5 %; a trailing ``%`` is accepted). Where a calculation solves for "the value left empty", the hint says so.
``tests/test_forms.py`` runs every ``example`` through the real operation.
"""
from __future__ import annotations

from ..forms import B, L, N, S, T, TA, TB, op, w  # noqa: F401  (B, TA kept available for later forms)
from .core import CURRENCIES

CURRENCY = S("currency", "Currency", [("", "none (plain numbers)")] + [(c, c) for c in CURRENCIES], advanced=True,
             hint="Only changes how amounts are written. Calculations never depend on it.")
PLACES = N("places", "Decimals shown for money", advanced=True, placeholder="2", hint="Display only; the calculation keeps full precision.")
CUR = [CURRENCY, PLACES]

FREQ = [("1", "annually (1)"), ("2", "semi-annually (2)"), ("4", "quarterly (4)"), ("12", "monthly (12)"), ("52", "weekly (52)"), ("365", "daily (365)")]
PAY = [("12", "monthly (12)"), ("1", "yearly (1)"), ("2", "twice a year (2)"), ("4", "quarterly (4)"), ("26", "every two weeks (26)"), ("52", "weekly (52)")]
TIMING = S("timing", "Payments are made", [("end", "at the end of each period"), ("begin", "at the start of each period")], advanced=True)
YEARLY = [("1", "once a year (1)"), ("2", "twice (2)"), ("4", "quarterly (4)"), ("12", "monthly (12)")]

ANNUITY_MODES = [("pv", "Present value of the payments"), ("fv", "Future value of saving"), ("payment_for_pv", "Payment that repays an amount (loan payment)"),
                 ("payment_for_fv", "Payment that reaches a target (savings plan)"), ("periods_for_pv", "Number of payments to repay an amount"),
                 ("periods_for_fv", "Number of payments to reach a target"), ("rate_for_pv", "Rate that fits a present value"), ("rate_for_fv", "Rate that fits a future value")]
NOT_RATE = ["pv", "fv", "payment_for_pv", "payment_for_fv", "periods_for_pv", "periods_for_fv"]
NOT_PERIODS = ["pv", "fv", "payment_for_pv", "payment_for_fv", "rate_for_pv", "rate_for_fv"]
NOT_PMT = ["pv", "fv", "periods_for_pv", "periods_for_fv", "rate_for_pv", "rate_for_fv"]
HAS_PV = ["fv", "payment_for_pv", "payment_for_fv", "periods_for_pv", "periods_for_fv", "rate_for_pv", "rate_for_fv"]
HAS_FV = ["payment_for_fv", "periods_for_fv", "rate_for_fv"]

FINANCE = [
    # ------------------------------------------------------------------------------------------------------------------ interest
    op("interest", "Interest", "Simple, compound or continuous interest. Fill in three of the four values; the empty one is calculated.",
       [S("mode", "Interest type", [("compound", "Compound"), ("simple", "Simple"), ("continuous", "Continuous")]),
        N("pv", "Principal (present value)", placeholder="1000", hint="Leave exactly one of principal, future value, rate and years empty. With none empty, the future value is calculated."),
        N("fv", "Future value", placeholder="empty = calculate it"), N("rate", "Annual rate (%)", placeholder="5"), N("years", "Time (years)", placeholder="10"),
        S("freq", "Compounded", FREQ, when=w("compound"))] + CUR,
       {"mode": "compound", "pv": "1000", "rate": "5", "years": "10", "freq": "12"}),
    op("rate_conversion", "Rate conversion", "Convert between nominal, effective, periodic and continuous rates; see equivalent rates for every compounding frequency.",
       [S("mode", "The rate you have is", [("nominal", "A nominal annual rate (APR) compounded n times a year"), ("effective", "An effective annual rate (APY)"),
                                           ("periodic", "The rate for one period"), ("continuous", "A continuously compounded annual rate")]),
        N("rate", "Rate (%)", required=True, placeholder="12"), S("freq", "Periods per year", FREQ, when=w("nominal", "periodic"))],
       {"mode": "nominal", "rate": "12", "freq": "12"}),
    op("real_rate", "Real and nominal rates", "The exact Fisher relation between a nominal rate, inflation and the real rate. Leave one empty.",
       [N("nominal", "Nominal rate (%)", placeholder="5"), N("inflation", "Inflation (%)", placeholder="2"), N("real", "Real rate (%)", placeholder="empty = calculate it")],
       {"nominal": "5", "inflation": "2"}),
    op("annuity", "Annuities", "Present and future value of regular payments, the payment, the number of payments or the rate (ordinary annuity or annuity due).",
       [S("mode", "Calculate", ANNUITY_MODES),
        N("pmt", "Payment each period", when=w(*NOT_PMT), placeholder="100"),
        N("rate", "Annual rate (%)", when=w(*NOT_RATE), placeholder="6"),
        S("perYear", "Payments per year", PAY),
        N("periods", "Number of payments", when=w(*NOT_PERIODS), placeholder="60"),
        N("pv", "Present value / starting balance", when=w(*HAS_PV), placeholder="0", hint="The amount to repay, or a balance already saved."),
        N("fv", "Target future value", when=w(*HAS_FV)), TIMING] + CUR,
       {"mode": "pv", "pmt": "100", "rate": "6", "periods": "60", "perYear": "12"}),
    op("perpetuity", "Perpetuities", "Value of a payment stream that never ends, with or without growth. Rates are per period.",
       [S("mode", "Calculate", [("pv", "Present value"), ("payment", "First payment"), ("rate", "Discount rate")]),
        N("payment", "First payment", when=w("pv", "rate"), placeholder="100"), N("rate", "Discount rate per period (%)", when=w("pv", "payment"), placeholder="5"),
        N("growth", "Growth per period (%)", placeholder="0"), N("pv", "Present value", when=w("payment", "rate")), TIMING] + CUR,
       {"mode": "pv", "payment": "100", "rate": "5", "growth": "0"}),
    # ------------------------------------------------------------------------------------------------------------------ loans
    op("loan", "Loan", "Payment, term, borrowing power or outstanding balance of a fixed-rate loan, with an optional fee and the resulting APR.",
       [S("mode", "Calculate", [("payment", "Payment (annuity loan)"), ("linear", "Payments of a linear loan (equal principal)"), ("term", "How long it takes to repay"),
                                ("borrow", "How much can be borrowed"), ("balance", "Outstanding balance after some payments")]),
        N("principal", "Loan amount", when=w("payment", "linear", "term", "balance"), placeholder="200000"),
        N("payment", "Payment each period", when=w("term", "borrow"), placeholder="1200"),
        N("rate", "Annual rate (%)", required=True, placeholder="6"),
        N("years", "Term (years)", when=w("payment", "linear", "borrow", "balance"), placeholder="30"),
        S("perYear", "Payments per year", PAY),
        N("afterPayments", "Payments already made", when=w("balance"), placeholder="60"),
        N("feeAmount", "Fee paid at the start", when=w("payment"), advanced=True, placeholder="0"), N("feePercent", "Fee as % of the loan", when=w("payment"), advanced=True, placeholder="0"),
        TIMING] + CUR,
       {"mode": "payment", "principal": "200000", "rate": "6", "years": "30", "perYear": "12"}),
    op("amortization", "Amortization schedule", "Every payment split into interest and principal, with extra payments, yearly totals and the balance over time.",
       [S("kind", "Repayment", [("annuity", "Level payments (annuity)"), ("linear", "Equal principal (linear)")]),
        N("principal", "Loan amount", required=True, placeholder="200000"), N("rate", "Annual rate (%)", required=True, placeholder="6"), N("years", "Term (years)", required=True, placeholder="30"),
        S("perYear", "Payments per year", PAY),
        N("extra", "Extra payment each period", placeholder="0"), N("lumpAmount", "One-off extra payment", advanced=True, placeholder="0"), N("lumpAt", "…made with payment number", advanced=True, placeholder="1"),
        S("rounding", "Rounding", [("cents", "Round each period to the smallest unit (real-life schedule)"), ("none", "No rounding (exact)")], advanced=True), TIMING] + CUR,
       {"kind": "annuity", "principal": "10000", "rate": "6", "years": "2", "perYear": "12", "extra": "100", "rounding": "cents"}),
    op("loan_compare", "Compare loans", "Fixed-rate loans side by side: payment, total interest, fees, cost of borrowing and APR.",
       [N("principal", "Loan amount", required=True, placeholder="200000"), S("perYear", "Payments per year", PAY),
        TB("scenarios", "Scenarios", [("name", "Name", "30 years at 6 %"), ("rate", "Annual rate (%)", "6"), ("years", "Years", "30"), ("fee", "Fee", "0")], shape="array", required=True,
           hint="Each row can also override the loan amount in the field above."), TIMING] + CUR,
       {"principal": "200000", "perYear": "12", "scenarios": [{"name": "30 years at 6 %", "rate": "6", "years": "30", "fee": "0"},
                                                               {"name": "15 years at 5.5 %", "rate": "5.5", "years": "15", "fee": "1500"}]}),
    # ------------------------------------------------------------------------------------------------------------------ investment
    op("roi", "Return on investment", "Gain relative to cost, with the annualized rate when you give the time.",
       [N("cost", "Amount invested", required=True, placeholder="1000"), N("value", "Final value", required=True, placeholder="1500"), N("income", "Income received meanwhile", placeholder="0"),
        N("years", "Time (years)", placeholder="3")] + CUR,
       {"cost": "1000", "value": "1500", "income": "100", "years": "3"}),
    op("cagr", "Compound annual growth rate", "The constant yearly rate between two values. Leave one of the four empty to solve for it.",
       [N("begin", "Beginning value", placeholder="100"), N("end", "Ending value", placeholder="200"), N("rate", "Growth rate (% a year)", placeholder="empty = calculate it"), N("years", "Years", placeholder="5")] + CUR,
       {"begin": "100", "end": "200", "years": "5"}),
    op("npv", "Net present value", "Discount a list of cash flows. Flow 0 is now; each next flow is one period later. Negative means money paid out.",
       [L("flows", "Cash flows (periods 0, 1, 2, …)", required=True, placeholder="-1000 300 400 500 200"), N("rate", "Discount rate per period (%)", required=True, placeholder="8"),
        S("perYear", "Periods per year", YEARLY, advanced=True)] + CUR,
       {"flows": ["-1000", "300", "400", "500", "200"], "rate": "8"}),
    op("dcf", "Discounted cash flow", "Value of a forecast of cash flows plus an optional terminal value, with the share of value that rests on the terminal assumption.",
       [S("mode", "Terminal value", [("none", "None (forecast years only)"), ("gordon", "Growing perpetuity (Gordon)"), ("multiple", "Multiple of the last cash flow")]),
        N("firstFlow", "Cash flow in year 1", placeholder="100"), N("growth", "Growth per year (%)", placeholder="5"), N("years", "Forecast years", placeholder="5"),
        L("flows", "…or enter the cash flows yourself (years 1, 2, …)", advanced=True, hint="If filled in, the three fields above are ignored."),
        N("rate", "Discount rate (% a year)", required=True, placeholder="10"),
        N("terminalGrowth", "Terminal growth (% a year)", when=w("gordon"), placeholder="2"), N("exitMultiple", "Exit multiple (× last cash flow)", when=w("multiple"), placeholder="8"),
        N("netDebt", "Net debt to subtract", advanced=True, placeholder="0")] + CUR,
       {"mode": "gordon", "firstFlow": "100", "growth": "5", "years": "5", "rate": "10", "terminalGrowth": "2", "netDebt": "200"}),
    op("irr", "Internal rate of return", "Every rate at which NPV is zero, found exactly. Warns when the IRR is not unique or does not exist.",
       [L("flows", "Cash flows (periods 0, 1, 2, …)", required=True, placeholder="-1000 300 400 500 200"), S("perYear", "Periods per year", YEARLY, advanced=True),
        N("financeRate", "Finance rate for the modified IRR (%)", advanced=True), N("reinvestRate", "Reinvestment rate for the modified IRR (%)", advanced=True)],
       {"flows": ["-1000", "300", "400", "500", "200"]}),
    op("payback", "Payback period", "When the running total of cash flows turns positive, plain and discounted.",
       [L("flows", "Cash flows (periods 0, 1, 2, …)", required=True, placeholder="-1000 300 400 500 200"), N("rate", "Discount rate per period (%) for discounted payback", placeholder="8"),
        S("perYear", "Periods per year", YEARLY, advanced=True)] + CUR,
       {"flows": ["-1000", "300", "400", "500", "200"], "rate": "8"}),
    op("investment_growth", "Growth scenarios", "What a starting amount plus regular contributions could become at several assumed rates, also in today's money.",
       [N("initial", "Starting amount", required=True, placeholder="1000"), N("contribution", "Contribution each period", placeholder="100"), N("years", "Years", required=True, placeholder="10"),
        S("perYear", "Contributions per year", PAY), L("rates", "Annual rates to compare (%)", required=True, placeholder="3 5 7"), N("inflation", "Inflation (% a year, optional)", placeholder="2"), TIMING] + CUR,
       {"initial": "1000", "contribution": "100", "years": "10", "perYear": "12", "rates": ["3", "5", "7"], "inflation": "2"}),
    # ------------------------------------------------------------------------------------------------------------------ economics
    op("inflation", "Inflation and purchasing power", "What prices or money are worth after inflation, from a rate or from price index values.",
       [S("mode", "Calculate", [("future_cost", "Future cost of today's amount"), ("purchasing_power", "Purchasing power of an amount in the future"), ("cpi", "Adjust with price index values"),
                                ("average_rate", "Average inflation between two index values")]),
        N("amount", "Amount", when=w("future_cost", "purchasing_power", "cpi"), placeholder="100"), N("inflation", "Inflation (% a year)", when=w("future_cost", "purchasing_power"), placeholder="3"),
        N("years", "Years", when=w("future_cost", "purchasing_power", "average_rate"), placeholder="10"),
        N("cpiFrom", "Index value, earlier", when=w("cpi", "average_rate"), placeholder="250"), N("cpiTo", "Index value, later", when=w("cpi", "average_rate"), placeholder="300")] + CUR,
       {"mode": "future_cost", "amount": "100", "inflation": "3", "years": "10"}),
    op("percent_change", "Percentage change", "Percent change, applying and undoing a percentage, successive changes, and percentage points versus percent.",
       [S("mode", "Task", [("change", "Percentage change between two values"), ("apply", "Apply a percentage"), ("reverse", "Undo a percentage"), ("successive", "Successive changes"),
                           ("points", "Percentage points between two rates")]),
        N("old", "Old value", when=w("change")), N("new", "New value", when=w("change")),
        N("value", "Value", when=w("apply", "reverse")), N("percent", "Percentage (%)", when=w("apply", "reverse"), placeholder="10"),
        L("percents", "Changes in order (%)", when=w("successive"), placeholder="10 -10 20"),
        N("rateA", "First rate (%)", when=w("points")), N("rateB", "Second rate (%)", when=w("points"))],
       {"mode": "change", "old": "80", "new": "100"}),
    op("elasticity", "Price elasticity of demand", "Midpoint or endpoint elasticity from two observations, or the exact point elasticity of a demand function.",
       [S("mode", "Method", [("midpoint", "Midpoint (arc) elasticity from two points"), ("endpoint", "Endpoint elasticity from two points"), ("function", "Point elasticity of a demand function")]),
        N("price1", "Price 1", when=w("midpoint", "endpoint")), N("quantity1", "Quantity 1", when=w("midpoint", "endpoint")),
        N("price2", "Price 2", when=w("midpoint", "endpoint")), N("quantity2", "Quantity 2", when=w("midpoint", "endpoint")),
        T("demand", "Demand Q(P)", when=w("function"), placeholder="100 - 2*P", hint="Write it with the variable P."), N("price", "Price P", when=w("function"), placeholder="20")] + CUR,
       {"mode": "midpoint", "price1": "10", "quantity1": "100", "price2": "12", "quantity2": "80"}),
    op("break_even", "Break-even", "Volume and revenue at which profit is zero, a target profit and the margin of safety (constant price and unit cost).",
       [N("fixedCosts", "Fixed costs", required=True, placeholder="10000"), N("price", "Price per unit", required=True, placeholder="25"), N("variableCost", "Variable cost per unit", required=True, placeholder="15"),
        N("targetProfit", "Target profit (optional)", placeholder="0"), N("expectedUnits", "Expected units sold (optional)", placeholder="1500")] + CUR,
       {"fixedCosts": "10000", "price": "25", "variableCost": "15", "targetProfit": "2000", "expectedUnits": "1500"}),
    op("cost_revenue", "Cost, revenue and profit", "Your cost and revenue (or price) functions: profit, marginal cost and revenue, the profit maximum and break-even quantities.",
       [T("cost", "Total cost C(q)", required=True, placeholder="100 + 2*q + 0.5*q^2", hint="Use the variable q for the quantity."),
        T("price", "Price function P(q) (the price at which q units sell)", placeholder="80 - q", hint="Fill in this or the revenue function, not both."),
        T("revenue", "or Revenue function R(q)", placeholder="80*q - q^2"), N("quantity", "Evaluate at quantity q", placeholder="10")] + CUR,
       {"cost": "100 + 2*q + 0.5*q^2", "price": "80 - q", "quantity": "10"}),
    op("market_equilibrium", "Supply and demand", "The market-clearing price and quantity from your demand and supply functions, with surplus, price controls and a per-unit tax.",
       [T("demand", "Quantity demanded Qd(P)", required=True, placeholder="100 - 2*P", hint="Use the variable P for the price."), T("supply", "Quantity supplied Qs(P)", required=True, placeholder="10 + 3*P"),
        N("tax", "Per-unit tax on sellers", placeholder="0"),
        S("mode", "Price control", [("none", "None"), ("ceiling", "Price ceiling"), ("floor", "Price floor")]),
        N("controlPrice", "Controlled price", when=w("ceiling", "floor"))] + CUR,
       {"demand": "100 - 2*P", "supply": "10 + 3*P", "tax": "5", "mode": "none"}),
    # ------------------------------------------------------------------------------------------------------------------ statistics and scenarios
    op("growth_compare", "Compare growth rates", "The compound growth rate of several series, ranked, with a chart that indexes each to 100.",
       [TB("series", "Series", [("name", "Name", "Revenue"), ("begin", "Beginning value", "100"), ("end", "Ending value", "150"), ("years", "Years", "5")], shape="array", required=True)],
       {"series": [{"name": "A", "begin": "100", "end": "150", "years": "5"}, {"name": "B", "begin": "50", "end": "90", "years": "6"}]}),
    op("trend", "Time-series trend", "Fit a trend to equally spaced values with the Graphing workspace's least squares, with growth statistics and an optional projection.",
       [L("values", "Values in time order", required=True, placeholder="100 108 117 126 138 149 161 175"),
        S("model", "Trend model", [("linear", "Linear"), ("exponential", "Exponential"), ("power", "Power"), ("logarithmic", "Logarithmic"), ("quadratic", "Quadratic")]),
        S("perYear", "Observations per year", YEARLY), N("forecast", "Extend the trend by (observations)", placeholder="0"), N("movingAverage", "Moving average window", advanced=True),
        N("start", "Number of the first observation", advanced=True, placeholder="1")] + CUR,
       {"values": ["100", "108", "117", "126", "138", "149", "161", "175"], "model": "exponential", "perYear": "1", "forecast": "3"}),
    op("sensitivity", "Sensitivity tables", "How NPV, a loan payment or a future value change across rates and terms.",
       [S("mode", "Table for", [("loan_payment", "Loan payment by rate and term"), ("future_value", "Future value by rate and term"), ("npv", "NPV across discount rates")]),
        N("amount", "Loan amount / starting amount", when=w("loan_payment", "future_value"), placeholder="200000"),
        N("contribution", "Contribution each period", when=w("future_value"), placeholder="0"),
        L("rates", "Annual rates (%)", when=w("loan_payment", "future_value"), placeholder="4 5 6"), L("yearsList", "Terms (years)", when=w("loan_payment", "future_value"), placeholder="15 20 30"),
        S("perYear", "Payments per year", PAY, when=w("loan_payment", "future_value")),
        L("flows", "Cash flows (periods 0, 1, 2, …)", when=w("npv"), placeholder="-1000 300 400 500 200"),
        N("rateFrom", "Lowest rate (%)", when=w("npv"), placeholder="0"), N("rateTo", "Highest rate (%)", when=w("npv"), placeholder="30"), N("steps", "Steps", when=w("npv"), placeholder="10"),
        TIMING] + CUR,
       {"mode": "loan_payment", "amount": "200000", "rates": ["4", "5", "6"], "yearsList": ["15", "20", "30"], "perYear": "12"}),
]
